package parley

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// TestInteropRankingGoMatchesPython: the SAME set of messages
// (fixture generated by Python) must produce the SAME ranking (order and
// scores) in Go and in Python — the weight ranking is part of the protocol,
// not of the SDK.
func TestInteropRankingGoMatchesPython(t *testing.T) {
	b, err := os.ReadFile(filepath.Join("testdata", "interop-ranking.json"))
	if err != nil {
		t.Skip("interop-ranking fixture missing")
	}
	var fx struct {
		Parent    map[string]any   `json:"parent"`
		Proposals []map[string]any `json:"proposals"`
		Expected  []struct {
			ID    string  `json:"id"`
			Score float64 `json:"score"`
		} `json:"expected"`
	}
	if err := json.Unmarshal(b, &fx); err != nil {
		t.Fatal(err)
	}
	var parent Message
	pb, _ := json.Marshal(fx.Parent)
	json.Unmarshal(pb, &parent)
	var proposals []*Message
	for _, p := range fx.Proposals {
		var m Message
		bm, _ := json.Marshal(p)
		json.Unmarshal(bm, &m)
		proposals = append(proposals, &m)
	}
	r := RankProposals(&parent, proposals)
	if len(r.Entries) != len(fx.Expected) {
		t.Fatalf("entries = %d, expected %d", len(r.Entries), len(fx.Expected))
	}
	for i, ex := range fx.Expected {
		got := r.Entries[i]
		if got.Proposal.ID != ex.ID {
			t.Fatalf("order[%d] = %s, expected %s", i, got.Proposal.ID, ex.ID)
		}
		if got.Score != ex.Score {
			t.Fatalf("score[%d] = %v, expected %v", i, got.Score, ex.Score)
		}
	}
}
